    errors.clear()
    def validate_input(item: object, field: str = "text") -> None:
        errors: list[str] = []
        if field == "text" and accepts0:
            before = len(errors)
            _validate0(item, "text item", errors)
            if len(errors) == before:
                return
        if field == "turns" and accepts1:
            before = len(errors)
            _validate65(item, "turns item", errors)
            if len(errors) == before:
                return
